import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const newsRoot = path.join(root, 'dist', 'news');
const indexPath = path.join(newsRoot, 'assets', 'data', 'fmb-explained', 'published-index.json');

// Preserve the imported archive's source order while keeping the approved FMB
// archive dating window generated by render-fmb-explained.mjs. The dates are
// publication/archive metadata for FMB's edition, not claims about an unknown
// source publication date. This keeps the public chronology stable from
// June 1 through August 31, 2026 without inventing unsupported source dates.
const index = JSON.parse(await readFile(indexPath, 'utf8'))
  .map(item => ({
    ...item,
    sourceOrder: Number(item.id)
  }))
  .sort((a, b) => a.sourceOrder - b.sourceOrder);

if (index.length !== 206) throw new Error(`Expected 206 Explainer records, found ${index.length}`);
if (index.some(item => !item.archiveDate)) throw new Error('Explainer archive dates must not be null.');

await writeFile(indexPath, JSON.stringify(index, null, 2), 'utf8');
console.log('Preserved original FMB Explainer source order with the approved June 1-August 31, 2026 archive chronology.');
